import numpy as npn = int(input("Enter the number of vectors "))vectors = []for i in range(n):    v = np.array(list(map(float, input("Enter v{i+1}: ").split())))    vectors.append(v)#gs ogu =[]for v in vectors:    temp = v.copy()    for prev in u:        proj = ((np.dot(v,prev))/(np.dot(prev,prev)))*prev        temp -=prev    u.append(temp)#normalize e = []for vector in u:    e.append(vector/np.linalg.norm(vector))        #results# Resultsprint("\nOrthogonal vectors:")for i, vector in enumerate(u):    print(f"u{i+1} =", vector)print("\nOrthonormal vectors:")for i, vector in enumerate(e):    print(f"e{i+1} =", vector)                